import {icon} from './icons.js';
import {num,fillStatus,DEMO_CONTAINERS} from './data.js';
import {hydrateOps,emptyOps,applyOperation,assignFleet} from './operations.js';
import {createRoadRouter} from './routing.js';
import {readImport} from './import-data.js';
import {savePhoto,getPhoto} from './photos.js';
import {cloudAvailable,cloudRequest,CLOUD_URL} from './team-client.js';
import {loadMapLibrary} from './map.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Нет наблюдения';
const roleName={owner:'Владелец',dispatcher:'Диспетчер',driver:'Водитель',viewer:'Наблюдатель'};
const eventNames={observe:'Наблюдение',service:'Остановка рейса',import:'Импорт площадок','edit-container':'Параметры площадки','truck-save':'Настройка машины','truck-delete':'Удаление машины','publish-runs':'Рейсы опубликованы','close-run':'Рейс закрыт',seed:'Перенос данных'};
export function createOperationsUI({state,render,persist,heading,modal,closeModal,toast,download}){
  let local;try{local=JSON.parse(localStorage.getItem('ecomind-operations-v2'));}catch{}
  state.ops=hydrateOps(local,state.containers);state.containers=state.ops.containers;try{localStorage.setItem('ecomind-operations-v2',JSON.stringify(state.ops));}catch{}
  let cloud=null,teamList=null,teamMembers=null,teamError='',cloudBusy=false,pendingImport=null,previewController=null,fleetResult=null,fleetError='',fleetBusy=false,historyFilter='',driverTruck='',demoStage=0,demoTimer=null,photoUrls=[];
  const router=createRoadRouter(),stamp=()=>crypto.randomUUID();
  function saveLocal(){localStorage.setItem('ecomind-operations-v2',JSON.stringify(state.ops));persist();}
  function refresh(){render({keepScroll:true});}
  function currentRole(){return cloud?.role||'owner';}
  async function dispatch(op){
    if(cloudBusy)throw new Error('Дождитесь завершения текущего сохранения.');cloudBusy=true;
    try{
      op={...op,id:stamp()};
      if(cloud){const result=await cloudRequest(`workspaces/${cloud.id}/changes`,{method:'POST',body:JSON.stringify({baseRevision:cloud.revision,op})});cloud.revision=result.revision;state.ops=result.snapshot;}
      else{const next=applyOperation(state.ops,op);localStorage.setItem('ecomind-operations-v2',JSON.stringify(next));state.ops=next;}
      state.containers=state.ops.containers;fleetResult=null;persist();return state.ops;
    }catch(e){if(cloud&&e.status===409)await pull();throw e;}finally{cloudBusy=false;}
  }
  async function pull(){if(!cloud)return;const result=await cloudRequest(`workspaces/${cloud.id}`);if(result.revision!==cloud.revision){cloud=result;state.ops=result.snapshot;state.containers=state.ops.containers;fleetResult=null;refresh();}}
  async function syncList(){if(!cloudAvailable())return;try{teamList=await cloudRequest('workspaces');teamError='';}catch(e){teamError=e.message;}if(state.page==='team')refresh();}
  async function openSpace(id){const result=await cloudRequest(`workspaces/${id}`);cloud=result;state.ops=result.snapshot;state.containers=state.ops.containers;teamMembers=await cloudRequest(`workspaces/${id}/members`);refresh();toast('Общее пространство подключено. Изменения сохраняются на сервере.');}
  async function uploadPhoto(id){if(!cloud||!id)return;const blob=await getPhoto(id);if(blob)await cloudRequest(`workspaces/${cloud.id}/photos/${id}`,{method:'PUT',headers:{'Content-Type':'image/jpeg'},body:blob});}
  async function manualObservation({containerId,fill,confidence,note,file}){const photoId=await savePhoto(file);await uploadPhoto(photoId);await dispatch({type:'observe',containerId,fill,confidence,note,photoId});closeModal();refresh();toast('Наблюдение добавлено в историю.');}
  function photoURL(id){return cloud?`/api/team/workspaces/${cloud.id}/photos/${id}`:'';}
  function historyChart(id){const c=state.containers.find(c=>c.id===id),events=state.ops.events.filter(e=>e.containerId===id&&Number.isFinite(e.fill)).slice(-30);const values=[...(c?.source==='demo'?[{fill:c.fill,at:null}]:[]),...events];
    if(values.length<2)return '<div class="history-chart-empty">График появится после двух наблюдений. Начальные примеры не считаются измерениями.</div>';
    const points=values.map((e,i)=>[30+i/Math.max(1,values.length-1)*530,130-e.fill*1.1]);return `<svg class="history-chart" viewBox="0 0 590 160" role="img" aria-label="История заполненности от 0 до 100 процентов">${[0,50,100].map(v=>`<path d="M30 ${130-v*1.1}H570" stroke="#cbd9ee" stroke-dasharray="4 5"/><text x="4" y="${134-v*1.1}" fill="#809bc4" font-size="10">${v}%</text>`).join('')}<path d="${points.map((p,i)=>`${i?'L':'M'}${p.join(',')}`).join(' ')}" fill="none" stroke="#397cf4" stroke-width="2.5"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#397cf4"><title>${date(values[i].at)} · ${values[i].fill}%</title></circle>`).join('')}<text x="30" y="154" fill="#8aa0c1" font-size="9">${date(values[0].at)}</text><text x="570" y="154" fill="#8aa0c1" text-anchor="end" font-size="9">${date(values.at(-1).at)}</text></svg>`;}
  function timeline(id='',limit=100){const items=state.ops.events.filter(e=>!id||e.containerId===id).slice(-limit).reverse();return items.length?`<div class="event-timeline">${items.map(e=>`<article class="timeline-event"><span class="event-icon">${icon(e.kind==='service'?'truck':e.photoId?'camera':'chart')}</span><div><div class="event-title"><strong>${eventNames[e.kind]||'Событие'}${Number.isFinite(e.fill)?` · ${num(e.fill)}%`:''}</strong><time>${date(e.at)}</time></div><p>${esc(e.containerId||'Пространство')} ${e.status?`· ${e.status==='done'?'Вывезено':e.status==='blocked'?'Нет доступа':'Пропущено'}`:''}</p>${e.note?`<p>${esc(e.note)}</p>`:''}<small>${esc(e.actor)}</small>${e.photoId?`<img class="history-photo" data-photo="${esc(e.photoId)}" alt="Фото наблюдения ${esc(e.containerId)}" ${cloud?`src="${photoURL(e.photoId)}"`:''} loading="lazy">`:''}</div></article>`).join('')}</div>`:'<div class="ops-empty">Здесь появятся реальные наблюдения, фотографии и результаты рейсов. Добавьте первое наблюдение.</div>';}
  function historyPanel(id){return `<div class="history-detail"><h3>История площадки</h3>${historyChart(id)}${timeline(id,20)}</div>`;}
  function historyPage(){return heading('У каждой площадки — своя история.','Наблюдения, фотографии и подтверждённые результаты вывоза.','ЖУРНАЛ НАБЛЮДЕНИЙ',false)+`<div class="ops-toolbar"><label class="field"><span>Площадка</span><select id="ops-history-filter"><option value="">Все события</option>${state.containers.map(c=>`<option value="${esc(c.id)}" ${historyFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><button class="button" data-op-action="export-history">${icon('download')}Скачать историю</button></div>${historyFilter?`<section class="panel content-panel">${historyChart(historyFilter)}</section>`:''}<section class="panel content-panel">${timeline(historyFilter)}</section>`;}
  function importPage(){const p=pendingImport;return heading('Реальные площадки. С вашей таблицы.','CSV или Excel → проверка → предпросмотр координат → сохранение.','ИМПОРТ ДАННЫХ',false)+`<section class="panel content-panel"><div class="import-intro"><span class="ops-big-icon">${icon('upload')}</span><div><h2>Загрузите реестр площадок</h2><p>Обязательные столбцы: id, name, lat, lng, capacity. Дополнительно: address, fill, type, mandatory. Пустая заполненность остаётся неизвестной. До 39 площадок в пространстве.</p></div></div><div class="ops-toolbar"><label class="button primary">${icon('upload')}Выбрать CSV / Excel<input id="ops-import-file" type="file" accept=".csv,.xlsx,.xls" hidden></label><button class="button" data-op-action="import-template">${icon('download')}Шаблон CSV</button></div><p class="ops-note">Файл читается на вашем устройстве. Существующие площадки с теми же ID будут обновлены; остальные сохранятся. Импорт подтверждает расположение только после вашей проверки.</p></section>${p?`<section class="panel content-panel" style="margin-top:20px"><div class="section-heading"><div><h2>Проверка таблицы</h2><p>${esc(p.sheet)} · корректных строк: ${p.containers.length}</p></div><span class="badge ${p.errors.length?'red':''}">${p.errors.length?'Есть ошибки':'Готово к проверке'}</span></div>${p.errors.length?`<div class="error-note">${p.errors.map(esc).join('<br>')}</div>`:''}<div id="import-preview-map" class="import-preview-map" aria-label="Предпросмотр координат импортируемых площадок"></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Площадка</th><th>Координаты</th><th>Объём, л</th><th>Заполнение</th></tr></thead><tbody>${p.containers.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.name)}</td><td>${c.lat}, ${c.lng}</td><td>${c.capacity}</td><td>${c.fill===null?'Нет оценки':c.fill+'%'}</td></tr>`).join('')}</tbody></table></div><label class="check-field" style="margin:20px 0"><input id="ops-import-verified" type="checkbox">Я проверил координаты и подтверждаю, что это реальные площадки</label><label class="check-field" style="margin:15px 0"><input id="ops-import-replace-demo" type="checkbox" checked>Заменить нетронутые демонстрационные площадки; сохранить реальные и ручные наблюдения</label><button class="button primary" data-op-action="import-save" ${p.errors.length?'disabled':''}>${icon('check')}Сохранить площадки</button></section>`:''}`;}
  function fleetPage(){return heading('Несколько машин. Один понятный план.','Распределение по объёму, времени смены и обязательным остановкам.','АВТОПАРК И ПЛАНИРОВАНИЕ',false)+`<div class="ops-toolbar"><button class="button" data-op-action="truck-add">${icon('plus')}Добавить машину</button><button class="button primary" data-op-action="fleet-plan" ${fleetBusy?'disabled':''}>${icon(fleetBusy?'refresh':'route',fleetBusy?'spin':'')}Распределить площадки</button><a class="button" href="#routes">Порог и правило отбора ${icon('arrow-right')}</a></div><div class="fleet-grid">${state.ops.trucks.map(t=>`<article class="panel truck-card"><span class="ops-big-icon">${icon('truck')}</span><h2>${esc(t.name)}</h2><div class="truck-spec"><strong>${num(t.capacity/1000,1)}<small>м³ · без учёта сжатия</small></strong><strong>${num(t.minutes/60,1)}<small>часов в смене</small></strong></div><p>База: ${t.lat.toFixed(4)}, ${t.lng.toFixed(4)}</p><button class="text-button" data-op-action="truck-edit" data-id="${esc(t.id)}">Настроить машину ${icon('settings')}</button></article>`).join('')||'<p class="ops-empty">Добавьте первую машину.</p>'}</div><div class="methodology">Приоритет: обязательные площадки, затем заполненность. Загрузка — вместимость контейнера × заполненность. Время — дорожное движение + обслуживание. Учитываются базы каждой машины. Плотность отходов, сжатие, ограничения мусоровоза и пробки пока не учитываются.</div>${fleetError?`<div class="error-note">${esc(fleetError)}</div>`:''}${fleetBusy?'<div class="road-status">Получаем дорожные расстояния и проверяем ограничения машин…</div>':''}${fleetResult?fleetResults():''}`;}
  function fleetResults(){const f=fleetResult;return `<section class="panel content-panel" style="margin-top:20px"><div class="section-heading"><div><h2>Распределение готово</h2><p>${f.plans.reduce((s,p)=>s+p.stops.length,0)} из ${f.selected} площадок · ${num(f.plans.reduce((s,p)=>s+p.plan.distance,0),2)} км по дорогам</p></div><button class="button primary" data-op-action="publish-runs" ${!f.plans.length?'disabled':''}>Передать водителям ${icon('arrow-right')}</button></div>${f.plans.map(p=>`<div class="fleet-result"><div><h3>${esc(p.truck.name)}</h3><p>${p.stops.length} остановок · ${num(p.load/1000,1)} / ${num(p.truck.capacity/1000,1)} м³ · ${num(p.plan.distance,2)} км · ${num(p.totalMinutes)} мин</p></div><div class="truck-load"><span style="width:${p.load/p.truck.capacity*100}%"></span></div><p>${p.plan.points.slice(1,-1).map(c=>esc(c.name)).join(' → ')}</p></div>`).join('')}${f.unassigned.length?`<div class="error-note"><strong>Не распределено: ${f.unassigned.length}</strong><br>${f.unassigned.map(x=>`${esc(x.id)}: ${esc(x.reason)}`).join('<br>')}</div>`:''}<p class="ops-note">Рейс фиксирует порядок остановок на момент публикации. Следующие наблюдения его не перезаписывают.</p></section>`;}
  function driverPage(){const runs=state.ops.runs.filter(r=>!driverTruck||r.truckId===driverTruck),run=runs.at(-1),pending=run?.tasks.filter(t=>t.status==='pending')||[],task=pending[0],c=state.containers.find(c=>c.id===task?.containerId),done=run?.tasks.filter(t=>t.status==='done').length||0;
    return heading('Следующая остановка. Всё под рукой.','Зафиксируйте вывоз или причину, по которой площадка недоступна.','ЭКРАН ВОДИТЕЛЯ',false)+`<div class="ops-toolbar"><label class="field"><span>Экипаж</span><select id="ops-driver-truck"><option value="">Последний рейс</option>${state.ops.trucks.map(t=>`<option value="${esc(t.id)}" ${driverTruck===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><a href="#fleet" class="button">Планирование ${icon('route')}</a></div>${!run?'<section class="panel content-panel ops-empty">Рейсов пока нет. Диспетчер должен распределить площадки и передать план водителям.</section>':`<div class="driver-layout"><section class="panel driver-card"><div class="driver-progress-label"><span>${esc(run.truckName)}</span><span>${run.tasks.length-pending.length} / ${run.tasks.length}</span></div><div class="driver-progress"><span style="width:${(run.tasks.length-pending.length)/run.tasks.length*100}%"></span></div>${c?`<span class="section-kicker">СЛЕДУЮЩАЯ ОСТАНОВКА</span><h2>${esc(c.name)}</h2><p>${esc(c.address)}</p><div class="driver-stop-data"><span>${esc(c.id)}</span><span>${c.fill===null?'Нет оценки':c.fill+'% заполнено'}</span>${c.mandatory?'<span>Обязательная</span>':''}</div><a class="button" href="https://www.openstreetmap.org/?mlat=${c.lat}&mlon=${c.lng}#map=17/${c.lat}/${c.lng}" target="_blank" rel="noopener">${icon('map')}Открыть площадку на карте</a><div class="field" style="margin-top:22px"><label for="ops-driver-note">Комментарий к остановке</label><textarea id="ops-driver-note" rows="3" maxlength="600" placeholder="Для пропуска укажите причину"></textarea></div><div class="driver-actions"><button class="button primary" data-op-action="service" data-status="done" data-run="${run.id}" data-id="${c.id}">${icon('check')}Вывезено · контейнер пуст</button><button class="button" data-op-action="service" data-status="blocked" data-run="${run.id}" data-id="${c.id}">${icon('warning')}Нет доступа</button><button class="button" data-op-action="service" data-status="skipped" data-run="${run.id}" data-id="${c.id}">Пропустить</button></div><p class="ops-note">Кнопка «Вывезено» фиксирует подтверждение водителя и наблюдение 0%. Пропуск не меняет заполненность.</p>`:`<div class="run-complete">${icon('check')}<h2>Рейс завершён</h2><p>Вывезено: ${done} · прочие результаты: ${run.tasks.length-done}</p></div>`}<div class="driver-run-metrics">План: ${num(run.distance,2)} км · движение ${num(run.duration/60)} мин<br>Создан ${date(run.createdAt)}</div></section><section class="panel content-panel"><h2>Остановки рейса</h2><div class="driver-task-list">${run.tasks.map((t,i)=>{const c=state.containers.find(c=>c.id===t.containerId);return `<div class="driver-task ${t.status}"><span>${t.status==='done'?'✓':i+1}</span><div><strong>${esc(c?.name||t.containerId)}</strong><small>${t.status==='pending'?'Ожидает':t.status==='done'?'Вывезено':t.status==='blocked'?'Нет доступа':'Пропущено'}${t.note?' · '+esc(t.note):''}</small></div></div>`;}).join('')}</div>${pending.length&&currentRole()!=='driver'?`<button class="text-button" data-op-action="close-run" data-run="${run.id}" style="margin-top:20px">Закрыть оставшиеся остановки с отметкой «пропущено»</button>`:''}</section></div>`}`;}
  const demoSteps=[['Утро: наблюдаем','В изолированном примере четыре контейнера достигли порога вывоза.','12 площадок','4 в приоритете'],['Планируем рейсы','Площадки распределяются по объёму машин и времени смены. Обязательные включаются всегда.','2 машины','4 остановки'],['Едем по дорогам','В рабочем планировщике путь строится сервисом OSRM по улицам Астаны.','Дорожный граф','Без прямых через здания'],['Подтверждаем вывоз','Водитель отмечает результат. Подтверждённый вывоз создаёт наблюдение 0%, пропуск сохраняет прежнее.','Журнал событий','История заполнения'],['Видим результат','Диспетчер видит выполненные и пропущенные остановки. Реальная экономия проверяется по GPS-трекам.','Статусы рейса','Открытая методика']];
  function demoPage(){const d=demoSteps[demoStage];return heading('Один день EcoMind. За одну минуту.','Изолированный демонстрационный сценарий. Ваши данные не изменяются.','ДЕМОНСТРАЦИЯ РАБОТЫ',false)+`<section class="demo-story"><div class="demo-step-kicker">ШАГ ${demoStage+1} ИЗ ${demoSteps.length} · ВСЕ СОБЫТИЯ СМОДЕЛИРОВАНЫ</div><h2>${d[0]}</h2><p>${d[1]}</p><div class="demo-counters"><span>${d[2]}</span><span>${d[3]}</span></div><div class="demo-visual stage-${demoStage}">${[94,86,42,78,32,91,56,67,23,72,48,64].map((fill,i)=>`<div class="demo-bin" style="--level:${demoStage>=3&&fill>=75?0:fill}%;--bin-color:${fillStatus(demoStage>=3&&fill>=75?0:fill).color}">${icon('bin')}<span>${demoStage>=3&&fill>=75?'✓':fill+'%'}</span></div>`).join('')}</div><div class="demo-controls"><button class="button primary" data-op-action="demo-play">${icon(demoTimer?'minus':'arrow-right')}${demoTimer?'Пауза':'Запустить'}</button><button class="button" data-op-action="demo-next">Следующий шаг ${icon('arrow-right')}</button><button class="button" data-op-action="demo-reset">Сначала</button></div><div class="demo-dots">${demoSteps.map((_,i)=>`<button class="${i===demoStage?'active':''}" data-op-action="demo-step" data-index="${i}" aria-label="Шаг ${i+1}"></button>`).join('')}</div></section><div class="methodology">Наглядный сценарий объясняет процесс. Он не имитирует реальные измерения воздуха и не записывает выдуманные события в журнал. Откройте «Автопарк», чтобы рассчитать рейсы по текущему набору.</div>`;}
  function teamPage(){return heading('Одна команда. Общая картина.','Роли, наблюдения и рейсы синхронизируются между устройствами.','КОМАНДНОЕ ПРОСТРАНСТВО',false)+(!cloudAvailable()?`<section class="panel content-panel team-intro"><span class="ops-big-icon">${icon('building')}</span><h2>Общая база находится в приватной версии</h2><p>GitHub Pages сохраняет данные на этом устройстве. Для совместной работы откройте облачный EcoMind и войдите через ChatGPT. Данные устройств можно перенести через JSON-резервную копию.</p><div class="ops-toolbar"><a class="button primary" href="${CLOUD_URL}/#team" target="_blank" rel="noopener">Открыть командную версию ${icon('external')}</a><button class="button" data-op-action="backup-export">${icon('download')}Резервная копия</button></div></section>`:`<section class="panel content-panel"><div class="section-heading"><div><h2>${cloud?esc(cloud.name):'Ваши пространства'}</h2><p>${teamList?.user?esc(teamList.user.email):'Вход через ChatGPT'}${cloud?' · '+roleName[cloud.role]+' · версия '+cloud.revision:''}</p></div><button class="button" data-op-action="team-refresh">${icon('refresh')}Обновить</button></div>${teamError?`<div class="error-note">${esc(teamError)}</div>`:''}${!teamList?'<p>Загружаем сведения об аккаунте…</p>':`<div class="team-spaces">${teamList.spaces.map(s=>`<button class="team-space ${cloud?.id===s.id?'active':''}" data-op-action="team-open" data-id="${s.id}"><strong>${esc(s.name)}</strong><small>${roleName[s.role]}</small></button>`).join('')||'<p>Пока нет общих пространств.</p>'}</div>${teamList.invitations.map(i=>`<div class="success-note">Приглашение в «${esc(i.name)}» · ${roleName[i.role]} <button class="text-button" data-op-action="team-join" data-id="${i.id}">Принять</button></div>`).join('')}<form id="ops-team-create" class="inline-form"><input name="name" aria-label="Название нового пространства" placeholder="Название квартала" maxlength="80" required><button class="button" type="submit">${icon('plus')}Создать пространство</button></form>`}${cloud?`<div class="cloud-connected"><span class="status-dot"></span>Общая база подключена. Автообновление каждые 30 секунд при открытой странице.</div><div class="ops-toolbar">${['owner','dispatcher'].includes(cloud.role)?'<button class="button" data-op-action="team-seed">Перенести сохранённые данные устройства</button>':''}<button class="button" data-op-action="team-local">Вернуться к данным устройства</button><button class="button" data-op-action="backup-export">${icon('download')}Копия JSON</button></div>${teamMembers?`<h3>Участники</h3><div class="team-members">${teamMembers.members.map(m=>`<div><span>${esc(m.email)}</span><span class="badge">${roleName[m.role]}</span>${cloud.role==='owner'&&m.role!=='owner'?`<button class="text-button" data-op-action="member-remove" data-id="${m.user_id}">Убрать доступ к данным</button>`:''}</div>`).join('')}</div>${cloud.role==='owner'?`<form id="ops-team-invite" class="inline-form"><input name="email" type="email" aria-label="Email участника" placeholder="Email участника" required><select name="role" aria-label="Роль участника"><option value="driver">Водитель</option><option value="dispatcher">Диспетчер</option><option value="viewer">Наблюдатель</option></select><button class="button primary" type="submit">Пригласить</button></form><p class="ops-note">Приглашение появится после входа с указанным email и действует 7 дней. Доступ к самому приватному сайту владелец предоставляет отдельно в настройках доступа Sites. Письма автоматически не отправляются.</p>${teamMembers.invites.map(i=>`<div class="pending-invite">${esc(i.email)} · ${roleName[i.role]} <button class="text-button" data-op-action="invite-remove" data-id="${i.id}">Отозвать</button></div>`).join('')}`:''}`:''}`:''}</section>`)+`<section class="panel content-panel" style="margin-top:20px"><h2>Данные под вашим контролем</h2><p>На устройстве — локальное хранение, фотографии в IndexedDB. В командном режиме — общая база и защищённое хранилище фото. Наблюдатель читает данные, водитель фиксирует наблюдения и вывоз, диспетчер управляет площадками и рейсами, владелец управляет участниками.</p><div class="ops-toolbar"><button class="button" data-op-action="backup-export">Скачать JSON</button><label class="button">Восстановить JSON<input type="file" id="ops-backup-file" accept=".json" hidden></label></div><p class="ops-note">JSON содержит историю и параметры. Фотографии хранятся отдельно; резервная копия содержит только ссылки на них.</p></section>`;}
  function truckForm(id){const t=state.ops.trucks.find(t=>t.id===id)||{id:stamp(),name:'Новый экипаж',capacity:6600,minutes:480,lat:51.128,lng:71.4115};modal('Настройка машины',`<form id="ops-truck-form" data-id="${t.id}"><div class="field"><label>Название<input name="name" maxlength="100" value="${esc(t.name)}" required></label></div><div class="form-grid"><div class="field"><label>Объём кузова, л<input type="number" name="capacity" min="100" max="100000" value="${t.capacity}" required></label></div><div class="field"><label>Смена, мин<input type="number" name="minutes" min="10" max="1440" value="${t.minutes}" required></label></div><div class="field"><label>Широта базы<input type="number" name="lat" step="any" min="-90" max="90" value="${t.lat}" required></label></div><div class="field"><label>Долгота базы<input type="number" name="lng" step="any" min="-180" max="180" value="${t.lng}" required></label></div></div><button type="submit" class="button primary">Сохранить</button>${id?`<button type="button" class="text-button" data-op-action="truck-delete" data-id="${id}" style="margin-left:20px">Удалить машину</button>`:''}</form>`);}
  function editContainer(id){const c=state.containers.find(c=>c.id===id);if(!c)return;modal('Параметры площадки',`<form id="ops-container-form" data-id="${esc(id)}"><div class="field"><label>Название<input name="name" value="${esc(c.name)}" maxlength="120" required></label></div><div class="field"><label>Адрес<input name="address" value="${esc(c.address)}" maxlength="250"></label></div><div class="form-grid"><div class="field"><label>Широта<input name="lat" type="number" step="any" min="-90" max="90" value="${c.lat}" required></label></div><div class="field"><label>Долгота<input name="lng" type="number" step="any" min="-180" max="180" value="${c.lng}" required></label></div><div class="field"><label>Вместимость, л<input name="capacity" type="number" min="1" max="100000" value="${c.capacity}" required></label></div><div class="field"><label>Тип<select name="type"><option ${c.type==='Смешанные'?'selected':''}>Смешанные</option><option ${c.type==='Переработка'?'selected':''}>Переработка</option></select></label></div></div><label class="check-field"><input name="mandatory" type="checkbox" ${c.mandatory?'checked':''}>Обязательный вывоз независимо от заполненности</label><label class="check-field" style="margin:15px 0"><input name="real" type="checkbox" ${c.locationSource==='real'?'checked':''}>Координаты подтверждены владельцем площадки</label><button type="submit" class="button primary">Сохранить параметры</button></form>`);}
  async function planFleet(){
    if(fleetBusy)return;fleetBusy=true;fleetError='';fleetResult=null;refresh();
    try{if(!state.ops.trucks.length)throw new Error('Добавьте хотя бы одну машину.');const signature=JSON.stringify([state.ops.trucks,state.containers,state.route,state.settings.stopMinutes]);const networks=[];
      for(const t of state.ops.trucks)networks.push(await router.getNetwork(state.containers,{id:'depot',name:'База '+t.name,lat:t.lat,lng:t.lng}));
      const split=assignFleet(networks,state.containers,state.ops.trucks,{...state.route,stopMinutes:state.settings.stopMinutes}),plans=[];
      for(let i=0;i<split.assignments.length;i++){const a=split.assignments[i];if(!a.stops.length)continue;const plan=await router.buildPlan(networks[i],a.stops),totalMinutes=plan.duration/60+a.stops.length*state.settings.stopMinutes;if(totalMinutes>a.truck.minutes){split.unassigned.push(...a.stops.map(c=>({id:c.id,reason:'Полный дорожный маршрут не помещается в смену'})));continue;}plans.push({...a,plan,totalMinutes});}
      if(signature!==JSON.stringify([state.ops.trucks,state.containers,state.route,state.settings.stopMinutes]))throw new Error('Данные изменились во время расчёта. Повторите планирование.');fleetResult={plans,unassigned:split.unassigned,selected:split.selected};
    }catch(e){fleetError=e.message;}finally{fleetBusy=false;if(state.page==='fleet')refresh();}
  }
  async function onRender(){
    const mode=document.getElementById('data-mode-status');if(mode)mode.textContent=cloud?'Общая база · '+roleName[cloud.role]:'Данные устройства';
    const name=document.querySelector('.workspace strong');if(name&&cloud)name.textContent=cloud.name;
    const role=currentRole(),reader=role==='viewer',driver=role==='driver';
    if(reader)document.querySelectorAll('[data-action="observation"],[data-action="save-observation"],[data-op-action="service"]').forEach(el=>{el.disabled=true;el.title='У вашей роли доступ только для чтения';});
    if(reader||driver)document.querySelectorAll('[data-op-action="truck-add"],[data-op-action="truck-edit"],[data-op-action="container-edit"],[data-op-action="publish-runs"],[data-op-action="import-save"],[data-action="reset"],#ops-backup-file,#ops-import-file').forEach(el=>{el.disabled=true;el.title='Доступно диспетчеру';});

    if(state.page!=='import'){previewController?.remove();previewController=null;}
    photoUrls.forEach(URL.revokeObjectURL);photoUrls=[];
    for(const img of document.querySelectorAll('[data-photo]:not([src])')){try{const blob=await getPhoto(img.dataset.photo);if(blob&&img.isConnected){const url=URL.createObjectURL(blob);photoUrls.push(url);img.src=url;}else if(!blob)img.alt='Фото недоступно на этом устройстве';}catch{img.alt='Фото недоступно';}}
    if(state.page!=='demo'&&demoTimer){clearInterval(demoTimer);demoTimer=null;}
    if(state.page==='team'&&!teamList&&!teamError&&cloudAvailable())syncList();
    if(state.page==='import'&&pendingImport?.containers.length){previewController?.remove();previewController=null;const target=document.getElementById('import-preview-map');if(target){await loadMapLibrary();if(!target.isConnected)return;const map=new window.maplibregl.Map({container:target,style:'https://tiles.openfreemap.org/styles/positron',center:[71.43,51.15],zoom:11});previewController=map;const bounds=new window.maplibregl.LngLatBounds();pendingImport.containers.forEach(c=>{bounds.extend([c.lng,c.lat]);const el=document.createElement('div');el.className='import-pin';el.textContent=c.id;new window.maplibregl.Marker({element:el}).setLngLat([c.lng,c.lat]).addTo(map);});map.fitBounds(bounds,{padding:45,maxZoom:15,duration:0});}else if(target)target.innerHTML='<p>Откройте раздел «Карта», чтобы загрузить картографический модуль, затем вернитесь к предпросмотру.</p>';}
  }
  async function runAction(button){const action=button.dataset.opAction,id=button.dataset.id;
    if(action==='truck-add'||action==='truck-edit')return truckForm(id);
    if(action==='container-edit')return editContainer(id);
    if(action==='truck-delete'){await dispatch({type:'truck-delete',truckId:id});closeModal();refresh();}
    if(action==='fleet-plan')return planFleet();
    if(action==='publish-runs'){if(!fleetResult)return;const runs=fleetResult.plans.map(p=>({truckId:p.truck.id,truckName:p.truck.name,stops:p.plan.points.slice(1,-1).map(c=>c.id),distance:p.plan.distance,duration:p.plan.duration,geometry:p.plan.geometry,snaps:p.plan.snaps}));await dispatch({type:'publish-runs',runs});location.hash='driver';toast('Рейсы переданы водителям.');}
    if(action==='service'){await dispatch({type:'service',runId:button.dataset.run,containerId:id,status:button.dataset.status,note:document.getElementById('ops-driver-note')?.value||''});refresh();toast('Результат остановки сохранён.');}
    if(action==='close-run'){await dispatch({type:'close-run',runId:button.dataset.run});refresh();}
    if(action==='export-history')download('ecomind-history.json',JSON.stringify(state.ops.events,null,2),'application/json');
    if(action==='backup-export')download('ecomind-backup.json',JSON.stringify(state.ops,null,2),'application/json');
    if(action==='import-template')download('ecomind-import-template.csv','id;name;address;lat;lng;capacity;fill;type;mandatory\r\nYOUR-001;Название реальной площадки;Адрес;51.1327;71.4249;1100;;Смешанные;да');
    if(action==='import-save'){if(!document.getElementById('ops-import-verified')?.checked)throw new Error('Подтвердите проверку координат перед импортом.');if(!pendingImport||pendingImport.errors.length)throw new Error('Исправьте ошибки таблицы.');await dispatch({type:'import',containers:pendingImport.containers,replaceDemo:Boolean(document.getElementById('ops-import-replace-demo')?.checked)});pendingImport=null;location.hash='containers';toast('Площадки импортированы. История прежних наблюдений сохранена.');}
    if(action==='demo-play'){if(demoTimer){clearInterval(demoTimer);demoTimer=null;}else demoTimer=setInterval(()=>{demoStage=(demoStage+1)%demoSteps.length;if(demoStage===demoSteps.length-1){clearInterval(demoTimer);demoTimer=null;}if(state.page==='demo')refresh();},7000);refresh();}
    if(action==='demo-next'){demoStage=(demoStage+1)%demoSteps.length;refresh();}
    if(action==='demo-reset'){demoStage=0;clearInterval(demoTimer);demoTimer=null;refresh();}
    if(action==='demo-step'){demoStage=Number(button.dataset.index);refresh();}
    if(action==='team-refresh'){await syncList();await pull();if(cloud)teamMembers=await cloudRequest(`workspaces/${cloud.id}/members`);refresh();}
    if(action==='team-open')await openSpace(id);
    if(action==='team-join'){const result=await cloudRequest('join',{method:'POST',body:JSON.stringify({inviteId:id})});await syncList();await openSpace(result.id);}
    if(action==='team-local'){cloud=null;teamMembers=null;let raw;try{raw=JSON.parse(localStorage.getItem('ecomind-operations-v2'));}catch{}state.ops=hydrateOps(raw);state.containers=state.ops.containers;refresh();}
    if(action==='team-seed'){let raw;try{raw=JSON.parse(localStorage.getItem('ecomind-operations-v2'));}catch{}const source=hydrateOps(raw);modal('Перенести данные устройства?',`<p>Будут перенесены ${source.containers.length} площадок и ${source.events.length} событий. Текущие данные общего пространства будут заменены; перед этим скачайте резервную копию.</p>`,`<button class="button" data-op-action="backup-export">Скачать копию общей базы</button><button class="button primary" data-op-action="team-seed-confirm">Перенести данные устройства</button>`);}
    if(action==='team-seed-confirm'){let raw;try{raw=JSON.parse(localStorage.getItem('ecomind-operations-v2'));}catch{}const source=hydrateOps(raw);for(const e of source.events)if(e.photoId)await uploadPhoto(e.photoId);await dispatch({type:'seed',snapshot:source,note:'Данные устройства перенесены в общее пространство'});closeModal();refresh();}
    if(action==='member-remove'||action==='invite-remove'){await cloudRequest(`workspaces/${cloud.id}/${action==='member-remove'?'members':'invites'}/${encodeURIComponent(id)}`,{method:'DELETE'});teamMembers=await cloudRequest(`workspaces/${cloud.id}/members`);refresh();}
  }
  document.addEventListener('click',async e=>{const button=e.target.closest('[data-op-action]');if(!button)return;e.preventDefault();try{button.disabled=true;await runAction(button);}catch(error){toast(error.message,'warning');}finally{button.disabled=false;}});
  document.addEventListener('change',async e=>{try{
    if(e.target.id==='ops-history-filter'){historyFilter=e.target.value;refresh();}
    if(e.target.id==='ops-driver-truck'){driverTruck=e.target.value;refresh();}
    if(e.target.id==='ops-import-file'){toast('Читаем и проверяем таблицу…','info');pendingImport=await readImport(e.target.files[0]);refresh();}
    if(e.target.id==='ops-backup-file'){const file=e.target.files[0];if(!file||file.size>2*1024*1024)throw new Error('JSON-копия должна быть до 2 МБ.');const snapshot=hydrateOps(JSON.parse(await file.text()),[]);if(!snapshot.containers.length)throw new Error('В копии нет корректных площадок.');pendingImport=null;await dispatch({type:'seed',snapshot});refresh();toast('Данные восстановлены из копии.');}
  }catch(error){toast(error.message,'warning');}});
  document.addEventListener('submit',async e=>{if(!e.target.id.startsWith('ops-'))return;e.preventDefault();const form=e.target,data=new FormData(form);try{
    if(form.id==='ops-truck-form'){await dispatch({type:'truck-save',truck:{id:form.dataset.id,name:data.get('name'),capacity:Number(data.get('capacity')),minutes:Number(data.get('minutes')),lat:Number(data.get('lat')),lng:Number(data.get('lng'))}});closeModal();refresh();}
    if(form.id==='ops-container-form'){await dispatch({type:'edit-container',containerId:form.dataset.id,patch:{name:data.get('name'),address:data.get('address'),capacity:Number(data.get('capacity')),lat:Number(data.get('lat')),lng:Number(data.get('lng')),type:data.get('type'),mandatory:data.has('mandatory'),locationSource:data.has('real')?'real':'demo'}});closeModal();refresh();}
    if(form.id==='ops-team-create'){const result=await cloudRequest('workspaces',{method:'POST',body:JSON.stringify({name:data.get('name')})});await syncList();await openSpace(result.id);}
    if(form.id==='ops-team-invite'){await cloudRequest(`workspaces/${cloud.id}/invites`,{method:'POST',body:JSON.stringify({email:data.get('email'),role:data.get('role')})});teamMembers=await cloudRequest(`workspaces/${cloud.id}/members`);refresh();toast('Приглашение создано. Участник увидит его после входа.');}
  }catch(error){toast(error.message,'warning');}});
  setInterval(()=>{if(cloud&&!cloudBusy&&!document.hidden)pull().catch(e=>{teamError=e.message;});},30000);
  return {page:page=>({history:historyPage,import:importPage,fleet:fleetPage,driver:driverPage,demo:demoPage,team:teamPage}[page]?.()),onRender,historyPanel,manualObservation,dispatch,cloud:()=>cloud,reset:async()=>{await dispatch({type:'seed',snapshot:emptyOps(DEMO_CONTAINERS),note:'Восстановлен исходный демонстрационный набор'});closeModal();refresh();},saveLocal};
}
